# Fixed-size chunking with overlap over tokens (here: words, for simplicity)
def chunk_fixed(tokens: list[str], size: int, overlap: int) -> list[tuple[int, int]]:
    if not 0 <= overlap < size:
        raise ValueError("overlap must be in [0, size)")
    step, spans, start = size - overlap, [], 0
    while True:
        end = min(start + size, len(tokens))
        spans.append((start, end))
        if end == len(tokens):
            return spans
        start += step
