# Structure-aware: split Markdown policy docs by headings, then paragraphs; keep heading path
import re

def chunk_markdown(doc_id: int, text: str, max_chars: int = 1500) -> list[dict]:
    chunks, path = [], []
    for block in re.split(r"\n(?=#{1,3} )", text):          # split before headings
        m = re.match(r"(#{1,3}) (.+)", block)
        if m:
            level = len(m.group(1))
            path = path[: level - 1] + [m.group(2).strip()]
        section, buf = " > ".join(path), ""
        for para in block.split("\n\n"):
            if buf and len(buf) + len(para) > max_chars:
                chunks.append((section, buf))
                buf = ""
            buf += para + "\n\n"
        if buf.strip():
            chunks.append((section, buf))
    # heading path stored as metadata AND prefixed to the embedded text
    return [
        {"document_id": doc_id, "chunk_index": i, "section": sec,
         "content": f"{sec}\n{c.strip()}"}
        for i, (sec, c) in enumerate(chunks)
    ]
